using OcctSharp.ExchangeRoots;
using OcctSharp.TransferRecords;
using OcctSharp.CopiedCollections;
namespace OcctSharp.Tests.Shared;
internal static class BatchBDExchangeWorkflow {
 internal static void Run(){Run(RootExchangeFormat.Step);Run(RootExchangeFormat.Iges);}
 internal static void Run(RootExchangeFormat format){string root=Path.Combine(Path.GetTempPath(),"OcctSharp.BD."+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string extension=format==RootExchangeFormat.Step?".step":".iges",input=Path.Combine(root,"input"+extension),output=Path.Combine(root,"output"+extension);using var box=ShapeFactory.CreateBox(2,3,4);using var moved=box.Transformed(ShapeTransform.CreateTranslation(8,0,0));using var shapes=OwnedShapeSet.Create(box,moved);var writerFormat=format==RootExchangeFormat.Step?WriterTransferFormat.Step:WriterTransferFormat.Iges;using(var writer=WriterTransferSession.Create(shapes,writerFormat)){if(!writer.TransferAndWrite(input).WriteSucceeded)throw new InvalidOperationException("BD input fixture write failed.");}using var workspace=ExchangeRootWorkspace.Open(input,format,new(2e-6,1e-7,1e-3));var data=workspace.Snapshot();if(data.Roots.Count<2||data.ModelCount<data.Roots.Count||data.FullPath!=Path.GetFullPath(input)||data.Sha256.Length!=64||data.PrivateRepairParameters.Count==0)throw new InvalidOperationException("BD initialized private source/root diagnostics failed.");var selected=data.Roots[0].Id;using var transfer=workspace.Transfer([selected,selected],RootTransferRoute.Entity);workspace.Dispose();if(!transfer.Completed||transfer.Roots.Count!=2||transfer.Roots.Any(x=>x.ModelNumber!=data.Roots[0].ModelNumber||x.ShapeCount<1)||transfer.ShapeCount<2||transfer.Sha256!=data.Sha256)throw new InvalidOperationException("BD repeated exact root-domain transfer failed.");using var result=transfer.GetShape(transfer.Roots[0].FirstShapeIndex);transfer.Dispose();if(!result.IsValid)throw new InvalidOperationException("BD independent root shape lifetime failed.");using var outputSet=OwnedShapeSet.Create(result);using(var writer=WriterTransferSession.Create(outputSet,writerFormat)){if(!writer.TransferAndWrite(output).WriteSucceeded)throw new InvalidOperationException("BD selected root export failed.");}using var read=format==RootExchangeFormat.Step?ShapeExchange.ReadStep(output):ShapeExchange.ReadIges(output);if(!read.IsValid||read.FaceCount<6||read.FaceCount>=12)throw new InvalidOperationException("BD independent selected-file readback failed.");}finally{Directory.Delete(root,true);}}
}
